from collections import deque
graph = {1: [2, 3], 2: [4], 3: [4], 4: [5, 6], 5: [7], 6: [7], 7: []}

def count_visits(start, track_seen):
    seen, queue, visits = {start}, deque([start]), 0
    while queue:
        node = queue.popleft()
        visits += 1
        for nb in graph[node]:
            if not track_seen or nb not in seen:
                seen.add(nb)
                queue.append(nb)
    return visits

print(count_visits(1, True), count_visits(1, False))

from collections import deque
graph = {"A": ["B", "C"], "B": ["E"], "C": ["D"], "D": ["E"], "E": ["F"], "F": []}

def bfs(start):
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist

